class Solution {
  public int[] minBitwiseArray(List<Integer> nums) {
    int[] ans = new int[nums.size()];
    for (int i = 0; i < ans.length; i++) {
      int num = nums.get(i);
      int trailingOnes = Integer.numberOfTrailingZeros(~num);
      // clear the highest bit of the trailing run of ones; an even number has no solution
      ans[i] = trailingOnes == 0 ? -1 : num - (1 << (trailingOnes - 1));
    }
    return ans;
  }
}
